from typing import Optional

from pydantic import BaseModel

from structured_rag.core.ports.llm import LLMPort


class OllamaAdapter(LLMPort):
    """Adapter for local Ollama instances."""

    def __init__(self, model_name: str):
        import ollama
        self.ollama = ollama
        self.model_name = model_name

    def generate(self, prompt: str, output_model: Optional[type[BaseModel]] = None) -> str:
        response = self.ollama.chat(
            model=self.model_name,
            messages=[{"role": "user", "content": prompt}]
        )
        return response['message']['content']

    def test_connection(self) -> str:
        response = self.ollama.chat(
            model=self.model_name,
            messages=[{"role": "user", "content": "say hello"}]
        )
        return response['message']['content']


class OllamaCloudAdapter(LLMPort):
    """Adapter for Ollama Cloud (hosted at ollama.com)."""

    def __init__(self, model_name: str, api_key: str):
        import ollama
        self.model_name = model_name
        self.client = ollama.Client(
            host="https://ollama.com",
            headers={"Authorization": f"Bearer {api_key}"}
        )

    def generate(self, prompt: str, output_model: Optional[type[BaseModel]] = None) -> str:
        response = self.client.chat(
            model=self.model_name,
            messages=[{"role": "user", "content": prompt}]
        )
        return response['message']['content']

    def test_connection(self) -> str:
        response = self.client.chat(
            model=self.model_name,
            messages=[{"role": "user", "content": "say hello"}]
        )
        return response['message']['content']

import json
from typing import Optional

from pydantic import BaseModel

from structured_rag.core.ports.llm import LLMPort


class OpenAIAdapter(LLMPort):
    def __init__(self, model_name: str, api_key: str, structured_outputs: bool = False):
        import openai
        self.model_name = model_name
        self.structured_outputs = structured_outputs
        self.client = openai.OpenAI(api_key=api_key)

    def generate(self, prompt: str, output_model: Optional[type[BaseModel]] = None) -> str:
        if self.structured_outputs and output_model is not None:
            response = self.client.beta.chat.completions.parse(
                model=self.model_name,
                messages=[
                    {"role": "system", "content": "You are a helpful assistant. Follow the response format instructions."},
                    {"role": "user", "content": prompt}
                ],
                response_format=output_model
            )
            parsed_response = response.choices[0].message.parsed
            return json.dumps({key: value for key, value in parsed_response.__dict__.items()})
        else:
            response = self.client.chat.completions.create(
                model=self.model_name,
                messages=[
                    {"role": "system", "content": "You are a helpful assistant."},
                    {"role": "user", "content": prompt}
                ]
            )
            return response.choices[0].message.content

    def test_connection(self) -> str:
        response = self.client.chat.completions.create(
            model=self.model_name,
            messages=[
                {"role": "system", "content": "You are a helpful assistant."},
                {"role": "user", "content": "say hello"}
            ]
        )
        return response.choices[0].message.content

from structured_rag.core.ports.llm import LLMPort


def get_llm_adapter(provider: str, model_name: str, api_key: str = "",
                     structured_outputs: bool = False, **kwargs) -> LLMPort:
    """Factory: create the right LLM adapter for a given provider."""

    if provider == "openai":
        from structured_rag.adapters.llm.openai_adapter import OpenAIAdapter
        return OpenAIAdapter(model_name, api_key, structured_outputs=structured_outputs)

    elif provider == "anthropic":
        from structured_rag.adapters.llm.anthropic_adapter import AnthropicAdapter
        return AnthropicAdapter(model_name, api_key)

    elif provider == "google":
        from structured_rag.adapters.llm.google_adapter import GoogleAdapter
        return GoogleAdapter(model_name, api_key, structured_outputs=structured_outputs)

    elif provider == "ollama":
        from structured_rag.adapters.llm.ollama_adapter import OllamaAdapter
        return OllamaAdapter(model_name)

    elif provider == "ollama_cloud":
        from structured_rag.adapters.llm.ollama_adapter import OllamaCloudAdapter
        return OllamaCloudAdapter(model_name, api_key)

    elif provider == "modal_vllm":
        from structured_rag.adapters.llm.modal_vllm_adapter import ModalVLLMAdapter
        return ModalVLLMAdapter(
            endpoint_url=model_name,  # config passes the URL as "model"
            api_key=api_key,
            **kwargs,
        )

    else:
        raise ValueError(
            f"Unknown provider: {provider!r}. "
            f"Supported: openai, anthropic, google, ollama, ollama_cloud, modal_vllm"
        )

from pydantic import BaseModel, create_model
from enum import Enum
from typing import Type, List


class PromptWithResponse(BaseModel):
    prompt: str
    response: str


class PromptingMethod(str, Enum):
    dspy = "dspy"
    fstring = "fstring"


class Experiment(BaseModel):
    test_name: str
    model_name: str
    prompting_method: PromptingMethod
    num_successes: int
    total_task_performance: int
    num_attempts: int
    success_rate: float
    average_task_performance: float
    total_time: int
    all_responses: list[PromptWithResponse]
    failed_responses: list[PromptWithResponse]

    class Config:
        protected_namespaces = ()


class SingleTestResult(BaseModel):
    prompt_with_response: PromptWithResponse
    is_valid: bool
    task_metric: int


# --- Output models for each task ---

class GenerateAnswer(BaseModel):
    answer: str


class RateContext(BaseModel):
    context_score: int


class AssessAnswerability(BaseModel):
    answerable_question: bool


class ParaphraseQuestions(BaseModel):
    paraphrased_questions: List[str]


class RAGASMetrics(BaseModel):
    faithfulness_score: float
    answer_relevance_score: float
    context_relevance_score: float


class GenerateAnswerWithConfidence(BaseModel):
    answer: str
    confidence: int


class GenerateAnswersWithConfidence(BaseModel):
    answers: List[GenerateAnswerWithConfidence]


class ClassifyDocument(BaseModel):
    category: Enum

    class Config:
        arbitrary_types_allowed = True


class ClassifyDocumentWithRationale(BaseModel):
    rationale: str
    category: Enum

    class Config:
        arbitrary_types_allowed = True


def create_enum(enum_name: str, enum_values: List[str]) -> Type[Enum]:
    """Dynamically create an Enum class with given values."""
    return Enum(enum_name, {value: value for value in enum_values})


def _ClassifyDocument(categories: List[str]) -> Type[BaseModel]:
    CategoriesEnum = create_enum("CategoriesEnum", categories)
    return create_model(
        'ClassifyDocument',
        category=(CategoriesEnum, ...)
    )


def _ClassifyDocumentWithRationale(categories: List[str]) -> Type[BaseModel]:
    CategoriesEnum = create_enum("CategoriesEnum", categories)
    return create_model(
        'ClassifyDocumentWithRationale',
        rationale=(str, ...),
        category=(CategoriesEnum, ...)
    )

from typing import Optional

from pydantic import BaseModel

from structured_rag.core.ports.llm import LLMPort


class GoogleAdapter(LLMPort):
    def __init__(self, model_name: str, api_key: str, structured_outputs: bool = False):
        import google.generativeai as genai
        self.genai = genai
        self.model_name = model_name
        self.structured_outputs = structured_outputs
        genai.configure(api_key=api_key)
        self.model = genai.GenerativeModel(model_name)

    def generate(self, prompt: str, output_model: Optional[type[BaseModel]] = None) -> str:
        if self.structured_outputs and output_model is not None:
            response = self.model.generate_content(
                prompt,
                generation_config=self.genai.GenerationConfig(
                    response_mime_type="application/json",
                    response_schema=output_model
                ),
            )
        else:
            response = self.model.generate_content(prompt)
        return response.text

    def test_connection(self) -> str:
        response = self.model.generate_content("say hello")
        return response.text

import json
from typing import Optional

import requests
from pydantic import BaseModel

from structured_rag.core.ports.llm import LLMPort


LLAMA3_PROMPT_TEMPLATE = """<|begin_of_text|>
<|start_header_id|>system<|end_header_id|>

Cutting Knowledge Date: December 2023
Today Date: 23 Jul 2024

You are a helpful assistant<|eot_id|>
<|start_header_id|>user<|end_header_id|>
{prompt}<|eot_id|>
<|start_header_id|>assistant<|end_header_id|>"""


class ModalVLLMAdapter(LLMPort):
    """Adapter for a Modal-deployed vLLM + Outlines endpoint.

    Deployment files live in structured_rag/adapters/llm/modal_deployment/.
    Deploy with: modal deploy vllm_outlines_setup.py

    The endpoint accepts POST requests with:
      {"prompts": [...], "with_outlines": bool, "output_model": <json_schema>}
    """

    def __init__(self, endpoint_url: str, api_key: str,
                 use_outlines: bool = True, use_llama3_template: bool = True,
                 timeout: int = 300):
        self.endpoint_url = endpoint_url
        self.use_outlines = use_outlines
        self.use_llama3_template = use_llama3_template
        self.timeout = timeout
        self.headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        }

    def _wrap_prompt(self, prompt: str) -> str:
        if self.use_llama3_template:
            return LLAMA3_PROMPT_TEMPLATE.format(prompt=prompt)
        return prompt

    def generate(self, prompt: str, output_model: Optional[type[BaseModel]] = None) -> str:
        wrapped = self._wrap_prompt(prompt)

        payload = {
            "prompts": [wrapped],
            "with_outlines": self.use_outlines and output_model is not None,
        }

        if self.use_outlines and output_model is not None:
            payload["output_model"] = output_model.schema()

        response = requests.post(
            self.endpoint_url, headers=self.headers,
            json=payload, timeout=self.timeout,
        )
        response.raise_for_status()

        results = response.json()

        if isinstance(results, list):
            # Outlines mode returns [{"id": "0", "answer": "..."}]
            return results[0]["answer"]
        elif isinstance(results, str):
            # Generator mode returns raw text
            return results
        else:
            return json.dumps(results)

    def generate_batch(self, prompts: list[str],
                       output_model: Optional[type[BaseModel]] = None) -> list[str]:
        """Send a batch of prompts in a single request. Returns responses in order."""
        wrapped = [self._wrap_prompt(p) for p in prompts]

        payload = {
            "prompts": wrapped,
            "with_outlines": self.use_outlines and output_model is not None,
        }

        if self.use_outlines and output_model is not None:
            payload["output_model"] = output_model.schema()

        response = requests.post(
            self.endpoint_url, headers=self.headers,
            json=payload, timeout=self.timeout,
        )
        response.raise_for_status()

        results = response.json()

        if isinstance(results, list) and results and isinstance(results[0], dict):
            # Outlines mode: sort by ID, extract answers
            sorted_results = sorted(results, key=lambda r: int(r["id"]))
            return [r["answer"] for r in sorted_results]
        elif isinstance(results, list):
            return results
        else:
            return [json.dumps(results)]

    def test_connection(self) -> str:
        return self.generate("say hello")
